<script setup lang="ts">import{onMounted,ref,watch}from'vue';import{Plus,Trash2,KeyRound,Variable}from'lucide-vue-next';import{api}from'../api';import Modal from'./Modal.vue';import EmptyState from'./EmptyState.vue';const props=defineProps<{projectId?:number}>();const values=ref<any[]>([]),open=ref(false),error=ref(''),form=ref({name:'',value:'',sensitive:false});const base=()=>props.projectId?`/api/projects/${props.projectId}/environment-variables`:'/api/environment-variables';async function load(){values.value=await api<any[]>(base())}async function save(){error.value='';try{await api(base(),{method:'POST',body:JSON.stringify(form.value)});open.value=false;form.value={name:'',value:'',sensitive:false};await load()}catch(e:any){error.value=e.message}}async function remove(id:number){await api(`${base()}/${id}`,{method:'DELETE'});await load()}onMounted(load);watch(()=>props.projectId,load)</script>
<template><section><div class="section-head"><div><h2>{{projectId?'项目环境变量':'全局环境变量'}}</h2><p>{{projectId?'覆盖同名全局变量，仅供当前项目使用。':'供当前用户的所有项目使用。'}}</p></div><button class="btn secondary" @click="open=true"><Plus/>添加变量</button></div><div class="resource-grid"><article v-for="item in values" :key="item.id" class="card resource-card"><div class="card-icon"><KeyRound v-if="item.sensitive"/><Variable v-else/></div><div class="grow"><h3>{{item.name}}</h3><p>{{item.sensitive?'敏感值 · 已加密':item.value||'空值'}}</p></div><button class="icon-btn danger-text" @click="remove(item.id)"><Trash2/></button></article><EmptyState v-if="!values.length" title="暂无环境变量"/></div><Modal v-model="open" title="添加环境变量" description="项目变量会覆盖同名全局变量。"><form @submit.prevent="save"><label>名称<input v-model="form.name" required pattern="[A-Z_][A-Z0-9_]*" placeholder="DEPLOY_ENV"></label><label>值<textarea v-model="form.value" required rows="4"></textarea></label><label class="checkbox-row"><input v-model="form.sensitive" type="checkbox">敏感值（加密且不再回显）</label><p v-if="error" class="error">{{error}}</p><div class="panel-actions"><button type="button" class="btn secondary" @click="open=false">取消</button><button class="btn">保存变量</button></div></form></Modal></section></template>
